&[
Command { name: "checks", usage: "north land checks --base BASE --head HEAD [--dry 0|1] [--safe-push PATH] [--red-fix ISSUE] [--outcome FILE]", run: slots::runner::run },
Command { name: "enqueue", usage: "north land enqueue [--repo DIR] [--message FILE]", run: enqueue::run },
Command { name: "follow", usage: "", run: after::follow::run },
Command { name: "profile", usage: "north land profile [--since DURATION] [--spans FILE]... [--landing BRANCH] [--repo NAME] [--last N] [--metric landing-p50|landing-p90|landing-projected|verification-p50|verification-p90]", run: trace::report::run },
Command { name: "promote", usage: "north land promote [--dry-run] [--shadow-minutes N] [--repo DIR]... [--checker PROGRAM]", run: promote::run },
Command { name: "reuse", usage: "north land reuse report [--since DURATION]", run: shadow::reuse_run },
Command { name: "replay", usage: "north land replay --base REV [--repo DIR] [--checker PROGRAM] TICKET...", run: replay::run },
Command { name: "requeue", usage: "north land requeue TICKET --reason TEXT [--repo DIR]", run: requeue::run },
Command { name: "sandbox", usage: "north land sandbox exec|child", run: north_land_sandbox::run },
Command { name: "scan", usage: "north land scan dep-gate|generated-registry|tool-removal|test-integrity BASE..HEAD", run: scans::run },
Command { name: "serve", usage: "north land serve [--once] [--all] [--repo DIR] [--checker PROGRAM] [--app-token PROGRAM]", run: serve::run },
Command { name: "shadow", usage: "north land shadow tick [--repo DIR]", run: shadow::run },
Command { name: "status", usage: "north land status TICKET [--repo DIR]", run: status::run },
Command { name: "urgent", usage: "north land urgent TICKET --reason TEXT [--repo DIR]", run: urgent::run },
Command { name: "clear-withdrawal", usage: "north land clear-withdrawal TICKET --reason TEXT [--repo DIR] [--noticed-by WHO]", run: scans::withdrawal::run },
Command { name: "withdraw", usage: "north land withdraw TICKET --reason TEXT [--repo DIR] [--noticed-by WHO] [--class CLASS]", run: withdraw::run },
Command { name: "break-glass", usage: "north land break-glass TICKET --reason TEXT --approval GATE [--repo DIR] [--app-token PROGRAM]", run: break_glass::run },
]
